cd /workspace && node -e "
const fs = require('fs');
const PizZip = require('pizzip');

// Read the docx file
const content = fs.readFileSync('testbed/docs/travel_summary.docx');
const zip = new PizZip(content);

// Get the document.xml
let docXml = zip.file('word/document.xml').asText();

// The note to append
const note = \`Maya Chen's Seattle travel records include a confirmed flight (C4C633), a cancelled hotel reservation (HR-7D93), and a confirmed car rental (CR-BE00). Please refer to these details for any future reference.\`;

// Create a new paragraph XML element to insert before </w:body>
const newParagraph = '<w:p><w:pPr><w:pStyle w:val=\"Normal\"/></w:pPr><w:r><w:t>' + note.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g, '&apos;') + '</w:t></w:r></w:p>';

// Insert before closing </w:body>
docXml = docXml.replace('</w:body>', newParagraph + '</w:body>');

// Update the zip
zip.file('word/document.xml', docXml);

// Write the updated docx
const updatedContent = zip.generate({ type: 'nodebuffer' });
fs.writeFileSync('testbed/docs/travel_summary.docx', updatedContent);
console.log('Note appended successfully.');
"

