cd /workspace && node -e "
const mammoth = require('mammoth');
const PDFDocument = require('pdfkit');
const fs = require('fs');

mammoth.extractRawText({path: 'testbed/docs/travel_summary.docx'}).then(result => {
  const text = result.value;
  const doc = new PDFDocument({ margin: 50, size: 'A4' });
  const stream = fs.createWriteStream('testbed/docs/travel_summary.pdf');
  doc.pipe(stream);

  const lines = text.split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      doc.moveDown(0.5);
      continue;
    }
    // Title
    if (trimmed === 'Travel Booking Summary') {
      doc.fontSize(18).font('Helvetica-Bold').text(trimmed, { align: 'center' });
      doc.moveDown(1);
    }
    // Section headers
    else if (['Flights', 'Hotels', 'Car Rentals'].includes(trimmed)) {
      doc.moveDown(0.5);
      doc.fontSize(14).font('Helvetica-Bold').text(trimmed);
      doc.moveDown(0.3);
    }
    // The appended note (last paragraph)
    else if (trimmed.startsWith(\"Maya Chen's Seattle travel records\")) {
      doc.moveDown(1);
      doc.fontSize(10).font('Helvetica-Oblique').text(trimmed, { align: 'left' });
    }
    // Regular booking entries
    else {
      doc.fontSize(9).font('Helvetica').text(trimmed);
    }
  }

  doc.end();
  stream.on('finish', () => {
    console.log('PDF created: testbed/docs/travel_summary.pdf');
    const stats = fs.statSync('testbed/docs/travel_summary.pdf');
    console.log('File size:', (stats.size / 1024).toFixed(1) + ' KB');
  });
});
"
